  "interventions": [
    {
      "description": "This study includes the use of surface electromyography (sEMG), video analysis, and questionnaires to assess trunk compensation patterns and their relationship with scoliosis, functional, quality-of-life, and pain parameters",
      "id": 1,
      "name": "Observational Assessment",
      "other_names": [],
      "type": {
